options.afterRender:
const container = document.getElementById('pvTree');
if (container) container.innerHTML = "";

const jsonString = context.data[0][0].pvTree;
const data = JSON.parse(jsonString);

const collBtn = document.getElementById('collBtn');
collBtn.addEventListener("click", () => {
  document.querySelectorAll('.children').forEach(el => {
    el.classList.add('hidden');
  });
  document.querySelectorAll('.expand-icon').forEach(icon => {
    icon.textContent = '▶';
  });
  Object.keys(localStorage)
    .filter(k => k.startsWith("treeExpanded:"))
    .forEach(k => localStorage.setItem(k, "false"));
});

function createButton(parent, className, textContent, eventFunct) {
  const btn = document.createElement('div');
  btn.className = className;
  btn.textContent = textContent;
  btn.addEventListener("click", (e) => eventFunct(e, parent));
  parent.appendChild(btn);
}


function buildTree(obj, container, path = []) {
  for (const key in obj) {
    const currentPath = [...path, key];

    // If have codes, is clickeable leaf
    if ('codes' in obj[key]) {
      const wrapper = document.createElement('div');
      wrapper.className = 'tree';
      const keyDiv = document.createElement('div');
      keyDiv.className = 'leaf';
      const nameText = document.createElement('div');
      nameText.textContent = key;
      nameText.className = 'nameText';
      keyDiv.appendChild(nameText);

      // Button holder
      const btnHolder = document.createElement('div');
      btnHolder.className = 'btnHolder';
      keyDiv.appendChild(btnHolder);

      //BUTTONS
      //Append Button
      createButton(btnHolder, 'leafBtn', '+L', (e, parent) => {
        e.stopPropagation();
        let currentTitle = context.grafana.replaceVariables("${title:csv}");

        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);
        let selectedPVs = context.grafana.replaceVariables("${pv:csv}").split(",");
        let selectedExtraAxisPVs = context.grafana.replaceVariables("${pvExtraAxis:csv}").split(",");

        for (const code of arrCodes) {
          if (!selectedPVs.includes(code)) {
            selectedPVs.push(code);
          }
          if (selectedExtraAxisPVs.includes(code)) {
            selectedExtraAxisPVs = selectedExtraAxisPVs.map(c => c != code);
            console.log(selectedExtraAxisPVs)
            context.grafana.locationService.partial({
              'var-pvExtraAxis': selectedExtraAxisPVs
            }, true);
          }
        }
        context.grafana.locationService.partial({
          'var-pv': selectedPVs,
          'var-title': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,
        }, true);
      })

      //Append (w extra axis) Button
      createButton(btnHolder, 'leafBtn', '+R', (e, parent) => {
        e.stopPropagation();
        let currentTitle = context.grafana.replaceVariables("${title:csv}");

        const arrCodes = JSON.parse(parent.parentElement.dataset.codes);
        let selectedPVs = context.grafana.replaceVariables("${pv:csv}").split(",");
        let selectedExtraAxisPVs = context.grafana.replaceVariables("${pvExtraAxis:csv}").split(",");
        // Adding to pv to query
        for (const code of arrCodes) {
          if (!selectedPVs.includes(code)) {
            selectedPVs.push(code);
          }
        }
        context.grafana.locationService.partial({
          'var-pv': selectedPVs,
          'var-title': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,
        }, true);

        if (selectedExtraAxisPVs[0] == "") {
          selectedExtraAxisPVs = arrCodes;
        }
        else {
          selectedExtraAxisPVs.push(...arrCodes);
        }

        context.grafana.locationService.partial({
          'var-pvExtraAxis': selectedExtraAxisPVs.join(",")
        }, true);
      })

      // Div Channel Name

      keyDiv.dataset.codes = JSON.stringify(obj[key]["codes"]);
      keyDiv.dataset.path = currentPath.join(">");
      keyDiv.addEventListener("click", () => {

        const arrCodes = JSON.parse(keyDiv.dataset.codes);
        context.grafana.locationService.partial({
          'var-pv': arrCodes,
          'var-title': keyDiv.dataset.path
        }, true);
        context.grafana.locationService.partial({
          'var-pvExtraAxis': ''
        }, true);
      });

      wrapper.appendChild(keyDiv);
      container.appendChild(wrapper);

    } else {
      // Create Section
      const value = obj[key];
      const wrapper = document.createElement('div');
      wrapper.className = 'tree';
      const keyDiv = document.createElement('div');
      keyDiv.className = 'key';
      const expandIcon = document.createElement('span');
      const nodePath = currentPath.join(" > ");
      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === "true";
      expandIcon.textContent = isExpanded ? '▼' : '▶';
      expandIcon.className = 'expand-icon';
      keyDiv.appendChild(expandIcon);
      const keyText = document.createElement('span');
      keyText.textContent = ` ${key}`;
      keyDiv.appendChild(keyText);
      const childrenContainer = document.createElement('div');
      childrenContainer.className = 'children';
      if (!isExpanded) {
        childrenContainer.classList.add('hidden');
      }

      if (typeof value === 'object' && value !== null) {
        buildTree(value, childrenContainer, currentPath);

        keyDiv.addEventListener("click", () => {
          const isHidden = childrenContainer.classList.toggle('hidden');
          expandIcon.textContent = !isHidden ? '▼' : '▶';
          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());
        });
      }

      wrapper.appendChild(keyDiv);
      wrapper.appendChild(childrenContainer);
      container.appendChild(wrapper);
    }
  }
}

buildTree(data, container);

