options.script:
// console.log(data);
// console.log(variables);
// console.log(options);


let series = data.series;


function toDate(secs,nanos) {
  return new Date(secs*1000 + nanos/1e6);
}
let layout = {
  title: variables.title.current.text,
  hovermode: 'x unified',
  hoverlabel: {
    font: { color: '#333', size: 12 }
  },
  xaxis: { title: 'Time' },
  yaxis: {
    showline: true,
    title: ""
  },
  yaxis2: {
    title: "",
    overlaying: 'y',
    side: 'right',
  }
};

if (series[0] != "no data"){


  let traces = [];


  const pvExtraAxis = variables.pvExtraAxis.current.text.split(",");
  series.forEach((s, i) => {

  let isStreaming = data.state == 'Streaming';
  let name, x, y;
  if (isStreaming){
    name = s.fields[1].config.displayName;
    x = s.fields[0].values.toArray();
    y = s.fields[1].values.toArray(); 
    // console.log(y);
    // let filtered = x.map((xi, idx) => [xi, y[idx]])
    //                 .filter(([xi, yi]) => !isNaN(yi));

    // x = filtered.map(([xi]) => xi);
    // y = filtered.map(([_, yi]) => yi);
    // console.log("Streming");
  }
  else{
    name = s.fields[1].name;
    x = Array.from(s.fields[0].values);
    y = Array.from(s.fields[1].values);
    // console.log("No Streming");
  }

  let pvInExtraAxis = pvExtraAxis.some(pv => pv.includes(name));
  let targetAxis =  pvInExtraAxis ? 'y2' : 'y1';


  traces.push({
    x: x,
    y: y,
    type: 'scatter',
    mode: 'lines',
    name: name,
    yaxis: targetAxis,
  });

   if(pvInExtraAxis){
    if(layout.yaxis2.title == ""){
      layout.yaxis2.title = name;
    }
    else{
      layout.yaxis2.title = `${name}, ${layout.yaxis2.title} `;
    }
   }
   else{
    if(layout.yaxis.title == ""){
      layout.yaxis.title = name;
    }
    else{
      layout.yaxis.title = `${name}, ${layout.yaxis.title} `;
    }
   }
  });


  return {
    data: traces,
    layout: layout
  };
}
